T.update({"opt:backup_replace:label": "Bestanden back-uppen en vervangen", "opt:backup_replace:tip": "Standaard aan. Voordat de run iets aanraakt, worden je invoer-regulation.bin en msg-archieven gekopieerd naar een back-upmap met tijdstempel (backups/ naast het programma), daarna vervangen de zojuist gegenereerde bestanden ze - één klik op Randomize back-upt en installeert dus allebei.\n\nDe randomized/-uitvoermap wordt nog steeds geschreven en bewaart de rapporten. Zet het uit om alleen de uitvoermap te schrijven en je bestanden met rust te laten; zet op elk moment terug met de knop Revert."})
T.update({"ui:backup": "Back-uppen", "ui:tip_backup": "Kopieert je invoer-regulation.bin en msg-archieven naar een back-upmap met tijdstempel (backups/ naast het programma). Voert niets uit.", "ui:revert": "Terugzetten", "ui:tip_revert": "Zet de recentste back-up terug: je oorspronkelijke regulation.bin en msg-archieven weer op hun plaats.", "ui:backup_none": "Niets om te back-uppen", "ui:backup_none_body": "Het invoerbestand is niet gevonden, dus er is niets om te back-uppen.", "ui:backup_done": "Back-up voltooid", "ui:backup_done_body": "Originele bestanden gekopieerd naar:\n{0}", "ui:revert_none": "Nog geen back-up", "ui:revert_none_body": "Er is geen back-up om terug te zetten. Gebruik eerst Back-uppen, of voer uit met Back-uppen en vervangen aan.", "ui:revert_title": "Terug naar de laatste back-up?", "ui:revert_body": "Dit zet de bestanden uit\n{0}\nweer op hun plaats en overschrijft wat er nu staat.", "ui:revert_done": "Teruggezet", "ui:revert_done_body": "{0} bestand(en) teruggezet uit:\n{1}", "ui:revert_failed": "Terugzetten mislukt", "ui:revert_failed_body": "Kon het back-upmanifest niet lezen:\n{0}"})
